import { describe, it, expect, vi } from 'vitest';
import { TodoStore } from './todoStore';

vi.mock('../utils/storage', () => ({
  loadTasks: () => [],
  saveTasks: vi.fn(),
  loadFilter: () => 'all',
  saveFilter: vi.fn()
}));

const DAY = 24 * 60 * 60 * 1000;

describe('due dates', () => {
  it('marks a past due date as overdue', () => {
    const store = new TodoStore();
    store.add('file taxes', Date.now() - DAY);
    const [task] = store.getVisibleTasks();
    expect(store.isOverdue(task)).toBe(true);
  });

  it('does not mark a future due date as overdue', () => {
    const store = new TodoStore();
    store.add('renew passport', Date.now() + DAY);
    const [task] = store.getVisibleTasks();
    expect(store.isOverdue(task)).toBe(false);
  });

  it('never marks a completed task as overdue', () => {
    const store = new TodoStore();
    store.add('old thing', Date.now() - DAY);
    const [task] = store.getVisibleTasks();
    store.toggle(task.id);
    expect(store.isOverdue(task)).toBe(false);
  });

  it('treats a task with no due date as not overdue', () => {
    const store = new TodoStore();
    store.add('someday');
    const [task] = store.getVisibleTasks();
    expect(store.isOverdue(task)).toBe(false);
  });
});

